contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept: caller (who will be msg.sender for calls from this contract) and amount to send to contract
    function run(address recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Record owner as seen via public getter and contract balance before funding
        address ownerBefore = c.owner();
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        // Fund c by sending Ether to its fallback
        if (fundAmount > 0) {
            c.f{value: fundAmount}();
        }

        // After funding, update observed balances
        uint256 cBalanceAfterFund = address(c).balance;
        uint256 recipientBalanceAfterFund = recipient.balance;

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observed values after attempted withdraw
        uint256 cBalanceFinal = address(c).balance;
        uint256 recipientBalanceFinal = recipient.balance;
        address ownerAfter = c.owner();

        // General rule:
        // If withdrawAll did not revert then (1) owner must equal the same owner as before,
        // (2) the recipient's balance increased by exactly the amount that c held just before the withdraw call,
        // and (3) c's balance decreased by that same amount (i.e. became zero relative to its pre-withdraw value).
        // If it reverted then no guarantees about balances are required here.
        assert(
            reverted || (
                ownerAfter == ownerBefore
                && recipientBalanceFinal == recipientBalanceAfterFund + cBalanceAfterFund
                && cBalanceFinal + cBalanceAfterFund == cBalanceAfterFund /* tautology to avoid underflow */
                && cBalanceFinal == 0
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // recipient: who should receive withdrawn funds; fundAmount: amount to fund C with before withdrawal
    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Observe owner and balances before funding
        address ownerBefore = c.owner();
        uint256 cBalBeforeFund = address(c).balance;
        uint256 recipientBalBefore = recipient.balance;

        // Fund c by sending Ether to its fallback (only if fundAmount > 0)
        if (fundAmount > 0) {
            c.withdrawAll{value: 0}(recipient); // no-op pattern to ensure no reordering; safe since will revert unless owner
            // Actually send Ether to c's fallback by calling it via low-level call
            (bool sent,) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // Observe contract balance just before withdraw attempt
        uint256 cBalBeforeWithdraw = address(c).balance;

        // Attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint256 cBalAfter = address(c).balance;
        uint256 recipientBalAfter = recipient.balance;
        address ownerAfter = c.owner();

        // If withdrawAll succeeded (did not revert) then:
        // - owner must remain the same
        // - recipient's balance increases by exactly c's balance just before the withdraw call
        // - c's balance after withdraw is decreased by that amount (i.e., becomes its prior minus that amount)
        assert(
            reverted || (
                ownerAfter == ownerBefore
                && recipientBalAfter == recipientBalBefore + cBalBeforeWithdraw
                && cBalAfter + cBalBeforeWithdraw == cBalBeforeWithdraw /* implies cBalAfter == 0 */
            )
        );
    }

    receive() external payable {}
}

