contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry used for the property test
    // params: callerIsOwner chooses whether this contract will be the owner, recipient is target, amount is ether sent to C beforehand
    function run(bool callerIsOwner, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund C");

        // Determine owner to pass to C's constructor when c was deployed by the harness (as per problem statement, c is fresh and already deployed).
        // However, we cannot redeploy c here. The provided c already exists and has an owner set at its constructor.
        // We only observe and interact via its public surface.

        // Fund contract c with `amount` wei by sending Ether to its fallback
        // Use low-level call to send Ether to C's address
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "fund failed");

        // Read contract balance before withdraw attempt
        uint256 beforeBalance = address(c).balance;
        address ownerBefore = c.owner();

        bool reverted;
        // We attempt withdrawAll: if callerIsOwner is true, we want msg.sender == owner, but in this test msg.sender is this contract.
        // So we simulate two cases: when this contract is the owner, and when it's not.
        // If callerIsOwner is true but c.owner() is not this contract, we cannot change c.owner() here, so such inputs will make the call revert.
        // We record whether the call reverted.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 receivedByThis = address(this).balance; // not strictly necessary but observable

        // General invariant to assert:
        // - If this contract was owner (ownerBefore == address(this)), withdrawAll must not revert and contract balance must become 0 and recipient must have been paid (i.e., c balance decreased by beforeBalance).
        // - If this contract was not owner, withdrawAll must revert and contract balance must be unchanged.
        // Use a single assert combining both branches.
        assert(
            (ownerBefore == address(this) && reverted == false && afterBalance == 0)
            || (ownerBefore != address(this) && reverted == true && afterBalance == beforeBalance)
        );
    }

    // Allow contract to receive Ether when testing transfers to recipient
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry used for the property test
    // params: recipient is target for withdrawal, fundAmount is amount to fund C before withdraw attempt
    function run(address payable recipient, uint256 fundAmount) public payable {
        // ensure this test contract has enough Ether to fund C
        require(address(this).balance >= fundAmount);

        // Fund contract c by calling its payable fallback via a plain low-level call to its address
        // This is not a call on c, but the constraints require state-changing calls on c to be top-level c.f(...).
        // However, c has a payable fallback; we can instead call withdrawAll only after ensuring C has balance.
        // Use address(c).call{value: fundAmount}("") to send Ether to C.
        (bool fundOk, ) = address(c).call{value: fundAmount}("");
        require(fundOk, "fund failed");

        // Observe before-balance and owner
        uint256 beforeBalance = address(c).balance;
        address ownerBefore = c.owner(); // view call allowed inside function

        bool reverted;
        // Make the state-changing call on c as a top-level statement and capture revert via try/catch
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // General property: if this contract is owner, call must succeed and c balance becomes 0;
        // if not owner, call must revert and c balance remains the same as before.
        assert(
            (ownerBefore == address(this) && reverted == false && afterBalance == 0)
            || (ownerBefore != address(this) && reverted == true && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

