contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: owner candidate to construct C was already set by harness;
    // we take a recipient and an amount to fund C via fallback and then attempt withdrawAll.
    function run(address payable recipient, uint256 fundAmount) public payable {
        // To fund C we require this contract has the funds
        require(address(this).balance >= fundAmount);

        // Record balance of c before funding
        uint256 beforeC = address(c).balance;
        // Fund c by sending Ether to it (fallback() payable)
        // note: calling address(c).call{value: fundAmount}("") is equivalent to sending Ether to fallback
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Record balances after funding
        uint256 afterFundC = address(c).balance;
        uint256 ourBefore = address(this).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read c.owner and c.balance
        address owner = c.owner();
        uint256 afterC = address(c).balance;
        uint256 ourAfter = address(this).balance;

        // General rule: if withdrawAll did not revert, then all Ether held by c after the call must be zero
        // and this contract's balance should have decreased by exactly the amount that left c (i.e., before->after movement).
        // We express that the entire c balance was moved out to recipient (so c.balance == 0), and that our balance
        // change equals negative of the amount we sent to c minus any gas but we cannot observe gas; instead we check
        // that c.balance is zero and that the only allowed case for non-revert is c.balance == 0 after call.
        // Also ensure the call succeeded implies owner must have been equal to address(this) (since only owner can withdraw).

        assert(reverted || (afterC == 0 && owner == address(this)));
    }

    receive() external payable {}
}

