        uint256 afterRecipient = address(recipient).balance;

        address owner = c.owner();

        // moved amounts (no underflow in asserts because we compute defensively)
        uint256 movedFromC = preWithdrawC >= postWithdrawC ? preWithdrawC - postWithdrawC : 0;
        uint256 recipGain = afterRecipient >= beforeRecipient ? afterRecipient - beforeRecipient : 0;

        // General rule:
        // If this contract is owner then withdrawAll must not revert and must transfer all of preWithdrawC to recipient (so c.balance becomes preWithdrawC - movedFromC == 0).
        // If this contract is not owner then withdrawAll must revert and must not move funds (postWithdrawC == preWithdrawC and recipGain == 0).
        assert(
            (owner == address(this) && !reverted && postWithdrawC == 0 && movedFromC == preWithdrawC && recipGain == movedFromC)
            ||
            (owner != address(this) && reverted && postWithdrawC == preWithdrawC && movedFromC == 0 && recipGain == 0)
        );
    }

    receive() external payable {}
}

