    // - deposit: amount of wei to fund contract C before withdrawal
    // - recipient: address to receive withdrawn funds
    function run(bool callerIsOwner, uint256 deposit, address payable recipient) public payable {
        require(address(this).balance >= deposit);

        // Determine owner passed to C's constructor: if callerIsOwner=true, owner is this test contract; otherwise some other address
        address ownerAddr = callerIsOwner ? address(this) : address(uint160(uint256(keccak256(abi.encodePacked(recipient, deposit)))));

        // Re-deploying C is not allowed here; but per harness the checker deploys a fresh c with some owner.
        // We cannot redeploy, so we must observe c.owner() and only proceed if it matches our chosen scenario.
        // To keep the test general, require that c was constructed with owner equal to either this or not (always true),
        // but we branch based on actual on-chain owner. We will read owner and then decide which call should succeed.

        address actualOwner = c.owner();

        // Fund C with deposit
        // We must ensure this contract has enough balance (checked above). Send Ether to C via fallback by calling with value to address(c).
        (bool sent, ) = address(c).call{value: deposit}("\x00");
        require(sent);

        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

