        // Attempt withdrawal: this contract calls withdrawAll as msg.sender
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule asserted:
        // - If this contract is the actual owner, withdrawAll must not revert and must transfer entire previous C balance to recipient (so C balance becomes 0 and this contract's balance unchanged unless recipient==this)
        // - If this contract is not the owner, withdrawAll must revert and leave C balance unchanged.
        // We observe transfers by changes in address(c).balance and address(this).balance; because recipient may be any address, we can only assert that when owner called successfully, C balance becomes 0; and when not owner, C balance unchanged and call reverted.

        assert((actualOwner == address(this) && !reverted && afterC == 0) || (actualOwner != address(this) && reverted && afterC == beforeC));
    }

    receive() external payable { }
}

