    function run(address initialOwner, address payable recipient, uint256 fundAmount, address caller) public payable {
        // Preconditions needed for sending funds into c: the test contract must hold fundAmount
        require(address(this).balance >= fundAmount);
        // The provided c is already deployed by the harness with some owner; we cannot redeploy it here.
        // We only interact through c's external surface. We'll observe owner(), address(c).balance

        // Record initial public observable values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Fund the contract c with fundAmount by using the fallback (contract c is payable on fallback)
        // This is a state-changing call and must be a top-level statement
        if (fundAmount > 0) {
            // send funds to c
            (bool sent, ) = address(c).call{value: fundAmount}("");
            // ensure the funding succeeded for the scenario; otherwise this path is invalid
            require(sent);
        }

        // Recompute balance after funding
        uint256 balanceAfterFund = address(c).balance;

        // Try to call withdrawAll from this contract (msg.sender will be this test contract)
        bool revertedByThis;
        try c.withdrawAll(payable(recipient)) {
            revertedByThis = false;
        } catch {
            revertedByThis = true;
        }

        // Now observe final balance of c and this contract (recipient balance observation via address is external; we can observe address(c).balance and that recipient is an address)
        uint256 balanceFinal = address(c).balance;

        // The general rule:
        // - If this contract (msg.sender) is ownerBefore then withdrawAll must not revert and must transfer entire balance to recipient, leaving c balance zero.
        // - If not ownerBefore then withdrawAll must revert and c balance must be unchanged from before the call.
        // We express that by comparing ownerBefore to address(this) and relating revert flag and balances.

        if (ownerBefore == address(this)) {
            // If we are owner, call should not revert and contract balance becomes zero
            assert(revertedByThis == false && balanceFinal == 0);
        } else {
            // If we are not owner, call should revert and balance remains as after funding
            assert(revertedByThis == true && balanceFinal == balanceAfterFund);
        }
    }

    // Allow this test contract to receive ETH so it can fund c
    receive() external payable {}
}

